/**
 * #1525 audio-window fixture — one real render proves the audible contract.
 *
 * `window` gates the source to 2–5 s inside an 8 s scene; `duck` additionally
 * sets the narration context so the source is multiplied by 0.25. The clip is
 * a 440 Hz sine generated by the driver, so ffmpeg's volumedetect can read the
 * gain directly. This entry is not registered in Root.tsx; the driver targets
 * it explicitly.
 */
import React from "react";
import { AbsoluteFill, Composition, registerRoot } from "remotion";
import { MediaBackground } from "./components/MediaBackground";
import { NarrationProvider } from "./components/narration-provider";
import type { MediaField } from "./types";

export const AUDIO_WINDOW_FIXTURE_VIDEO = "audio-window-fixture.mp4";

const BASE_MEDIA: MediaField = {
  type: "video",
  path: `assets/${AUDIO_WINDOW_FIXTURE_VIDEO}`,
  animation: "none",
  volume: 1,
  audioIn: 2,
  audioOut: 5,
  audioFadeIn: 0.25,
  audioFadeOut: 0.25,
  duckUnderNarration: true,
  duckLevel: 0.25,
};

type FixtureProps = { scenario?: "window" | "duck" };

const FixtureScene: React.FC<FixtureProps> = ({ scenario = "window" }) => (
  <AbsoluteFill style={{ background: "#000" }}>
    <NarrationProvider active={scenario === "duck"}>
      <MediaBackground media={BASE_MEDIA} duration={8} />
    </NarrationProvider>
  </AbsoluteFill>
);

export const AudioWindowFixtureRoot: React.FC = () => (
  <Composition
    id="AudioWindowFixture"
    component={FixtureScene as unknown as React.FC<Record<string, unknown>>}
    durationInFrames={240}
    fps={30}
    width={360}
    height={640}
    defaultProps={{ scenario: "window" }}
  />
);

registerRoot(AudioWindowFixtureRoot);
